routes={d['id']:d['slug']+'.html' for d in data}

for d in data:
 options=''.join(f'<article>{image(file,title)}<h3>{title}</h3><p>{text}</p></article>' for title,text,file in d['options'])
 related=[x for x in data if x['id']!=d['id']][:3]
 body=f'''<nav class="breadcrumbs" aria-label="Ruta de navegación"><a href="index.html">Inicio</a><span>/</span><a href="servicios.html">Tratamientos</a><span>/</span><span>{d['title']}</span></nav><section class="treatment-hero"><div><h1>{d['headline']}</h1><p>{d['desc']}</p><a class="btn pri" href="contacto.html?tratamiento={d['id']}">Agenda una evaluación {arrow}</a></div>{image(d['hero'],d['title'])}</section><nav class="detail-navigation" aria-label="En esta página"><a href="#que-es">Qué es</a><a href="#opciones">Opciones</a><a href="#proceso">Tu visita</a><a href="#cuidados">Cuidados</a><a href="#preguntas">Preguntas</a></nav><section class="sec treatment-explainer" id="que-es"><div><h2>Conoce tu tratamiento.</h2><p>{d['intro']}</p><p>En Nident empezamos por escucharte. El plan, las alternativas y el presupuesto se conversan después de la evaluación.</p><p class="small-note">Información general. La indicación de un tratamiento necesita una evaluación individual.</p></div><figure>{image(d['model'],'Imagen ilustrativa de '+d['title'])}<figcaption>Fotografía o modelo de referencia.</figcaption></figure></section><section class="sec treatment-options" id="opciones"><div class="heading-row"><h2>Opciones para<br>conversar en consulta.</h2><p>Un cuidado que responde a tus necesidades.</p></div><div class="detail-options">{options}</div></section><section class="sec treatment-process" id="proceso"><div><h2>Así te acompañamos.</h2><ol>{''.join(f'<li><span>{i+1:02}</span><p>{text}</p></li>' for i,text in enumerate(d['steps']))}</ol></div>{image(d['hero'],'Atención e imagen de referencia para '+d['title'])}</section><section class="sec treatment-care" id="cuidados">{image('hero-banner-img3.webp','Diente 3D con cepillo dental')}<div><h2>El cuidado continúa en casa.</h2><ul class="check-list">{''.join('<li>'+x+'</li>' for x in d['care'])}</ul><a class="text-link" href="cuidados.html">Más hábitos de cuidado {arrow}</a></div></section><section class="sec treatment-faq" id="preguntas"><h2>Resolvamos tus dudas.</h2>{''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in d['faqs'])}<p class="small-note">Fuente de información: <a href="{d['source']}" target="_blank" rel="noopener noreferrer">guía de salud dental {arrow}</a>.</p></section><section class="related-treatments"><h2>También puedes conocer.</h2><div>{''.join(f'<a href="{x["slug"]}.html">{image(x["model"],x["title"])}<h3>{x["title"]}</h3>{arrow}</a>' for x in related)}</div></section><section class="band final-cta"><div><h2>Tu próxima visita empieza aquí.</h2><p>Elige una sede y conversemos sobre tu sonrisa.</p></div><a class="btn pri" href="contacto.html?tratamiento={d['id']}">Reserva tu cita {arrow}</a></section>'''
 page(d['slug'],d['title'],body)

testimonials=[('Mariana','Ortodoncia','Me gustaría sentirme acompañada durante mis controles y entender cada paso de mi tratamiento.','avatar-small-avatar2.webp'),('Lucía','Primera visita infantil','Busco una primera visita con paciencia, para que mi hija conozca el consultorio sin presión.','child-smile.webp'),('Elena','Cuidado para adultos mayores','Quiero conocer mis opciones de rehabilitación y decidir con información clara.','about-img8.webp'),('Andrea','Cuidado preventivo','Valoro un espacio donde pueda preguntar y aprender a cuidar mi sonrisa en casa.','avatar-small-avatar3.webp')]
testimonials_html=f'''<section class="sec testimonial-section" id="testimonios"><div class="heading-row"><div><h2>Historias que nos<br>gustaría acompañar.</h2><p>Testimonios ilustrativos para mostrar el diseño. No son reseñas reales.</p></div><div class="testimonial-controls"><button type="button" data-testimonial-prev aria-label="Historia anterior">‹</button><button type="button" data-testimonial-next aria-label="Historia siguiente">›</button></div></div><div class="testimonial-stage" aria-live="polite">{''.join(f'<article class="testimonial-slide {"active" if i==0 else ""}" '+('' if i==0 else 'hidden')+f'>{image(file,"Retrato de referencia")}<div><span>Historia ilustrativa · {service}</span><blockquote>“{quote}”</blockquote><p>{name} <span>· Personaje de ejemplo</span></p></div></article>' for i,(name,service,quote,file) in enumerate(testimonials))}</div><div class="testimonial-dots">{''.join(f'<button type="button" data-testimonial="{i}" aria-label="Ver historia {i+1}" aria-pressed="{str(i==0).lower()}"></button>' for i in range(4))}</div></section>'''

plans=[('Sonrisa al día','89','Evaluación y orientación preventiva',['Evaluación odontológica','Orientación de higiene','Plan de cuidado personalizado'],'hero-banner-img3.webp','7'),('Pequeñas sonrisas','79','Una primera visita para Nident Kids',['Evaluación infantil','Conversación con el acompañante','Guía de hábitos por edad'],'hero-banner-img2.webp','2'),('Primer paso con brackets','99','Conoce tus opciones de ortodoncia',['Evaluación inicial','Opciones de alineación','Orientación del siguiente estudio'],'hero-banner-img4.webp','1')]
def plans_section(full=False):
 return f'''<section class="sec plans-section" id="planes"><div class="heading-row"><div><h2>Un primer paso<br>para cada sonrisa.</h2><p>Planes de evaluación con precios ilustrativos.</p></div>{'' if full else '<a class="text-link" href="promociones.html">Conoce los planes '+arrow+'</a>'}</div><div class="plans-grid">{''.join(f'<article>{image(file,"Ilustración dental 3D")}<h3>{name}</h3><p>{desc}</p><div class="plan-price">S/ {price}<span>Precio de ejemplo</span></div><ul>{"".join("<li>"+item+"</li>" for item in includes)}</ul><a class="btn ghost" href="{("contacto.html?tratamiento="+id) if full else "promociones.html"}">{"Elegir este plan" if full else "Ver qué incluye"} {arrow}</a></article>' for name,price,desc,includes,file,id in plans)}</div><p class="small-note">Promociones de demostración: no son ofertas vigentes. Los tratamientos, radiografías y procedimientos adicionales no están incluidos. El presupuesto real se define tras la evaluación.</p></section>'''
social=f'''<section class="sec social-community" id="comunidad"><div class="heading-row"><div><h2>Sonrisas que también<br>se comparten.</h2><p>Un espacio para hábitos, novedades y pequeños momentos de cuidado.</p></div><a class="text-link" href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer">Explora Instagram {arrow}</a></div><div class="social-posts"><a href="cuidados.html">{image('child-smile.webp','Cuidado dental infantil')}<span>En familia</span><h3>Una rutina que crece con ellos.</h3></a><a href="ortodoncia.html">{image('model-braces.jpg','Sonrisa con brackets')}<span>Tu sonrisa</span><h3>Brackets: conoce tus opciones.</h3></a><a href="cuidados.html">{image('product-brush.jpg','Cepillo dental rosa')}<span>En casa</span><h3>Pequeños hábitos, cada día.</h3></a><a href="nosotros.html#espacios">{image('clinic-room.webp','Espacio de clínica dental')}<span>El consultorio</span><h3>Un lugar para sentirte bien.</h3></a></div><div class="community-links"><a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer">Instagram {arrow}</a><a href="https://www.facebook.com/" target="_blank" rel="noopener noreferrer">Facebook {arrow}</a><a href="https://www.tiktok.com/" target="_blank" rel="noopener noreferrer">TikTok {arrow}</a><a href="https://www.youtube.com/shorts/9eQ80NNSI58" target="_blank" rel="noopener noreferrer">YouTube {arrow}</a></div><p class="small-note">Contenido editorial de la maqueta. Las cuentas reales de Nident aún no están vinculadas.</p></section>'''

home=(root/'index.html').read_text(encoding='utf-8')
home=home.replace('<section class="sec visit-section">',testimonials_html+plans_section()+social+'<section class="sec visit-section">')
# Primary catalog cards now explain, rather than jump straight into booking.
for cls in ['treatment-tile','family-card']:
 pattern=r'(<a[^>]*href=")contacto\.html\?tratamiento=(\d)("[^>]*class="'+cls+r'[^>]*>)'
 home=re.sub(pattern,lambda m:m[1]+routes[m[2]]+m[3],home)
home=re.sub(r'(<a class="treatment-tile[^>]*href=")contacto\.html\?tratamiento=(\d)(")',lambda m:m[1]+routes[m[2]]+m[3],home)
# Photo service gallery and family sections are educational entry points too.
start=home.index('<section class="sec service-gallery">');end=home.index('<section class="sec clinic-section',start)
chunk=home[start:end]
for id,url in routes.items():chunk=chunk.replace('contacto.html?tratamiento='+id,url)
home=home[:start]+chunk+home[end:]
start=home.index('<section class="sec family-section">');end=home.index('<section class="kids-feature',start)
chunk=home[start:end]
for id,url in routes.items():chunk=chunk.replace('contacto.html?tratamiento='+id,url)
home=home[:start]+chunk+home[end:]
(root/'index.html').write_text(home,encoding='utf-8')

services=(root/'servicios.html').read_text(encoding='utf-8')
for id,url in routes.items():services=services.replace('href="contacto.html?tratamiento='+id+'">Reserva una evaluación','href="'+url+'">Conoce el tratamiento')
services=services.replace('<section class="band final-cta">',plans_section()+'<section class="band final-cta">')
